#define PROFILES_COUNT (sizeof(profiles) / sizeof(*profiles))


static void run_test_vector(int iter, uint32_t ctr_len, const struct test_vectors *t)
{
	uint8_t derived_key[64]; // longest NIST key_out is 320b
	int i;

	kdf_ctr_cmac_aes_fixed((uint8_t *)t->KI,
			       (t->KI_size_in_bytes * 8),
			       ctr_len,
			       (uint8_t *)t->FixedInputData,
			       t->FixedInputData_size_in_bytes,
			       derived_key,
			       (t->KO_size_in_bytes * 8));

	printf("%d: ", iter);
	for (i = 0; i < t->KO_size_in_bytes; i++)
		printf("%02x", derived_key[i]);
	printf("\n");

	assert(!memcmp(derived_key, t->KO, t->KO_size_in_bytes));
}

void test_kdf(void)
{
	uint32_t ctr_len = 0;

	for (unsigned int i = 0; i < PROFILES_COUNT; i++) {
		const struct profile *current_profile = profiles + i;

		switch (current_profile->prf) {
		case PRF_CMAC_AES192:
			printf("PRF = CMAC_AES192\n");
			break;
		case PRF_CMAC_AES256:
			printf("PRF = CMAC_AES256\n");
			break;
		case PRF_CMAC_AES128:
			printf("PRF = CMAC_AES128\n");
			break;
		default:
			assert(0);
			break;
		}

		switch (current_profile->ctrlocation) {
		case CTRLOCATION_BEFORE_FIXED:
			printf("CTRLOCATION = BEFORE_FIXED\n");
			break;
		default:
			assert(0);
			break;
		}

		switch (current_profile->rlen) {
		case RLEN_8_BITS:
			ctr_len = 8;
			printf("RLEN = 8_BITS\n");
			break;
		case RLEN_16_BITS:
			ctr_len = 16;
			printf("RLEN = 16_BITS\n");
			break;
		case RLEN_24_BITS:
			ctr_len = 24;
			printf("RLEN = 24_BITS\n");
			break;
		case RLEN_32_BITS:
			ctr_len = 32;
			printf("RLEN = 32_BITS\n");
			break;
		default:
			assert(0);
			break;
		}

		for (unsigned int j = 0; j < current_profile->tests_vectors_count; j++)
			run_test_vector(j, ctr_len, current_profile->tests_vectors[j]);
	}
}
